        ptrace(PTRACE_INTERRUPT,fixture.pid,nullptr,nullptr)==0 && waitpid(fixture.pid,&status,__WALL)==fixture.pid && WIFSTOPPED(status);
#if defined(__x86_64__)
    using Registers=user_regs_struct;
#else
