            {*mapped,page,1,0,0,0});
        auto unmapped=executeMemorySyscall(pid,process.targetDescription().host,MemorySyscall::Unmap,
            {*mapped,page,0,0,0,0});
        operations=protectedPage && unmapped && operations;
