    printf("%d failed target syscall checks\n",failures);
    if(init) {
        printf("CE_VM_RESULT=%s\n",failures ? "FAILED" : "PASSED"); fflush(stdout);
        reboot(RB_POWER_OFF); for(;;) pause();
    }
