static void clearArmFault() { faultTarget = 0; faultStage = 0; }
struct Checks {
    const char* mode;
    unsigned count = 0, failed = 0;
    void operator()(bool ok, const char* name) {
        ++count; failed += !ok; totalFailures += !ok;
